// Import of required libraries
import { test, expect, getBaseUrl, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { fillRegistrationCredentials } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(60000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    // This test never submits the register form and never authenticates, so it needs no
    // credential: both values below are scratch input typed to prove the retained test ids
    // address live, editable fields.
    const errors: string[] = [];
    page.on('pageerror', (err) => errors.push(err.message));

    await page.goto(`${baseUrl}/register`);
    await expect(page).toHaveURL(`${baseUrl}/register`);

    await fillRegistrationCredentials(page, "scope-check-user", "scope-check-pass");

    await expect(page.getByTestId("username-input")).toHaveValue("scope-check-user");
    await expect(page.getByTestId("password-input")).toHaveValue("scope-check-pass");

    expect(errors).toHaveLength(0);
});
